const BASE_CENTER=id=>{const r=MOL_BY_ID.get(id),names=[...new Set(RINGS[r.component].flat())];return [0,1,2].map(i=>names.reduce((s,n)=>s+r.atoms[n][i],0)/names.length);};
const PAIR_CENTER=[0,1,2].map(i=>(BASE_CENTER(3)[i]+BASE_CENTER(70)[i])/2);
